namespace ZapretManager {
public static class Tests {
 static List<string> lines=new List<string>();static int failures;
 static void Check(bool ok,string name){lines.Add((ok?"PASS: ":"FAIL: ")+name);if(!ok)failures++;}
 public static void Preview(Form form){PreviewConvenience(form);Directory.CreateDirectory(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"tests"));if(form is MainForm)((MainForm)form).CapturePages(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"tests"));using(var b=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(b,new Rectangle(Point.Empty,form.Size));b.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"tests","app-preview.png"));}using(var f=new FaceForm()){f.Show();Application.DoEvents();using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,f.Size));b.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"tests","faceit-preview.png"));}f.Close();}}
 public static void PreviewExclusions(){using(var f=new ExclusionForm()){f.Show();Application.DoEvents();using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,f.Size));b.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"tests","exclusions-preview.png"));}f.Close();}}
 public static void PreviewConvenience(Form owner){
  string directory=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"tests");Directory.CreateDirectory(directory);
  Form[] forms={new ProfileForm(),new HistoryForm(p=>{}),new PreferencesForm(()=>{}),new AppPicker(p=>{}),new LatencyForm(),new UpdateForm()};
  foreach(var form in forms)using(form){form.Show(owner);Application.DoEvents();using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,form.Size));bitmap.Save(Path.Combine(directory,form.GetType().Name+"-preview.png"));}form.Close();}
 }
 static string Normalize(string text){return text.Replace("\r\n","\n").TrimEnd();}
 public static async Task<int> Run(string[] args){string report=args.Length>0?args[0]:Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"tests","report.txt");string reference=args.Length>1?args[1]:"";bool live=args.Contains("--live");Directory.CreateDirectory(Path.GetDirectoryName(report));lines.Add("Zapret 2 native 3.2 — "+DateTime.Now.ToString("o"));var token=CancellationToken.None;var settings=Core.Load();string original=File.ReadAllText(Core.PathOf("manager-base.txt"));
  try{
   foreach(string game in new[]{"off","udp","tcp","all"})foreach(string ip in new[]{"none","loaded","any"}){var s=Core.Read<Settings>(Core.PathOf("manager-settings.json"));s.Game=game;s.IPSet=ip;string text=Core.Build(s);await Core.Validate(text,token);Check(true,"winws2 accepts "+game+"/"+ip);if(reference!="")Check(Normalize(text)==Normalize(File.ReadAllText(Path.Combine(reference,game+"-"+ip+".txt"))),"configuration matches PowerShell "+game+"/"+ip);}
   foreach(var c in Network.Candidates()){string b=Network.TuneBase(original,c);await Core.Validate(Core.Build(settings,b),token);Check(true,"candidate dry-run "+c.Id);if(reference!="")Check(Normalize(b)==Normalize(File.ReadAllText(Path.Combine(reference,c.Id+".base"))),"strategy matches PowerShell "+c.Id);}
   Check(Core.ValidateIPSet("# comment\n1.2.3.4/24\n2001:db8::/32")==2,"IPv4/IPv6 validator");bool rejected=false;try{Core.ValidateIPSet("1.2.3.4/33");}catch{rejected=true;}Check(rejected,"invalid CIDR rejected");rejected=false;try{Network.ParseServer("1.2.3.4:65536");}catch{rejected=true;}Check(rejected,"invalid game port rejected");
   string hosts=Core.MergeHosts("127.0.0.1 localhost\r\n1.2.3.4 old.example keep.example\r\n","8.8.8.8 old.example");Check(hosts.Contains("127.0.0.1 localhost")&&hosts.Contains("1.2.3.4 keep.example")&&hosts.Contains("8.8.8.8 old.example"),"Hosts preserves unrelated mappings");
   string ef=Core.PathOf("files\\faceit-game-exclude.txt");byte[] old=File.Exists(ef)?File.ReadAllBytes(ef):null;try{File.WriteAllText(ef,"192.0.2.1\r\n",Encoding.ASCII);var text=Core.Build(settings);var udp=text.Split('\n').Where(l=>l.Contains("--filter-udp="));Check(udp.All(l=>l.Contains("faceit-game-exclude.txt"))&&!text.Split('\n').Where(l=>l.Contains("--filter-tcp=")).Any(l=>l.Contains("faceit-game-exclude.txt")),"FACEIT exclusion applies only to UDP");}finally{if(old==null)File.Delete(ef);else File.WriteAllBytes(ef,old);}
   await MockStun();await RelayTest();
   var good=new Measurement();good.Samples.Add(new Sample {Core=true,Success=true,Seconds=.4,Target="HTTP"});var bad=new Measurement();bad.Samples.Add(new Sample {Core=true,Success=false,Seconds=.01,Target="HTTP"});Check(Network.Winner(new[]{new Candidate {Id="current",Measurement=good},new Candidate {Id="split",Measurement=bad}}).Id=="current","failed mandatory probe cannot win");var uncertain=new Measurement();uncertain.Samples.AddRange(good.Samples);uncertain.Samples.Add(new Sample {Target="Discord media voice",Unknown=true});Check(uncertain.Valid&&uncertain.Media==0,"unknown media is not success");uncertain.Samples.Add(new Sample {Target="Discord media screen",Success=false});Check(!uncertain.Valid,"media failure excludes candidate");
   var before=Process.GetProcessesByName("curl").Select(p=>p.Id).ToArray();using(var stop=new CancellationTokenSource()){stop.CancelAfter(100);bool cancelled=false;try{await Core.Run(Path.Combine(Environment.SystemDirectory,"curl.exe"),"--noproxy \"*\" --max-time 30 http://192.0.2.1:81",stop.Token,32000);}catch(OperationCanceledException){cancelled=true;}Check(cancelled,"cancellation interrupts subprocess");}Check(!Process.GetProcessesByName("curl").Any(p=>!before.Contains(p.Id)),"cancelled curl process cleaned up");
   if(args.Contains("--updates")){var ipset=await Core.Fetch("https://raw.githubusercontent.com/Flowseal/zapret-discord-youtube/main/.service/ipset-service.txt");Check(Core.ValidateIPSet(ipset)>0,"real IPSet update downloads and validates");var hostsUpdate=await Core.Fetch("https://raw.githubusercontent.com/Flowseal/zapret-discord-youtube/main/.service/hosts");Check(Core.MergeHosts("127.0.0.1 localhost",hostsUpdate).Contains("127.0.0.1 localhost"),"real Hosts update downloads, validates, merges; system Hosts untouched");lines.Add("UPDATE: "+await Core.Updates());Check(true,"official winws2 update API reachable");}
   if(args.Contains("--integration"))await Integration(token);
   if(live){var snap=Core.Backup();var liveResults=new List<Candidate>();try{Core.Guard();foreach(var c in Network.Candidates()){lines.Add("RUN: "+c.Id);File.WriteAllLines(report,lines,Encoding.UTF8);await Core.Apply(settings,token,Network.TuneBase(original,c));if(Core.State()!="Running")Core.Control("On");await Task.Delay(700);c.Measurement=await Network.Measure(2,token);liveResults.Add(c);lines.Add("NETWORK: "+c.Id+" "+c.Measurement.Good+"/"+c.Measurement.Samples.Count+" P90="+c.Measurement.P90.ToString("0.000"));foreach(var p in c.Measurement.Samples)if(!p.Success)lines.Add("DETAIL: "+p.Target+" "+p.Error);}
    Core.Write(Path.Combine(Path.GetDirectoryName(report),"strategies.json"),liveResults);Check(Network.Winner(liveResults)!=null,"at least one strategy passes mandatory live checks");
   }finally{Core.Restore(snap);}Check(Core.State()==snap.State&&new[]{"manager-base.txt","config.txt","manager-settings.json"}.All(f=>File.ReadAllBytes(Core.PathOf(f)).SequenceEqual(File.ReadAllBytes(Path.Combine(snap.Directory,f)))),"all strategies tested; exact restoration of settings/config/service state");
    var faces=await Network.Faceit("",token);Core.Write(Path.Combine(Path.GetDirectoryName(report),"faceit.json"),faces);Check(faces.Count(r=>r.Kind=="region")==8,"all 8 FACEIT regions tested");Check(faces.Where(r=>r.Name.StartsWith("discord.com")||r.Name.StartsWith("www.youtube.com")).All(r=>r.Result.StartsWith("Проверка HTTPS пройдена")),"Discord and YouTube coexist with FACEIT");
   }
  }catch(Exception e){Check(false,e.ToString());}lines.Add("Failures: "+failures);File.WriteAllLines(report,lines,Encoding.UTF8);return failures==0?0:1;
 }
 static async Task Integration(CancellationToken token){var snap=Core.Backup();try{Core.Guard();Core.Control("Off");Check(Core.State()=="Stopped","native stop service");Core.Service="zapret2-native-test";try{await Core.Install(token);Check(Core.State()=="Running","native SCM create/start test service");Core.Control("Restart");Check(Core.State()=="Running","native service restart");await Core.Remove(token);Check(Core.State()=="NotInstalled","native test service remove");}finally{if(Core.State()!="NotInstalled")Core.Remove(token).GetAwaiter().GetResult();Core.Service="zapret2";}}finally{Core.Service="zapret2";Core.Restore(snap);}Check(Core.State()==snap.State,"original service restored after install/remove tests");
  using(var cts=new CancellationTokenSource()){bool cancelled=false;try{await Network.Tune(cts.Token,(p,m)=>cts.CancelAfter(100),null);}catch(OperationCanceledException){cancelled=true;}Check(cancelled,"autotuner cancellation completes without mutex ownership error");}Check(!File.Exists(Core.PathOf("autotune-pending.json"))&&Core.State()==snap.State&&new[]{"manager-base.txt","config.txt","manager-settings.json"}.All(f=>File.ReadAllBytes(Core.PathOf(f)).SequenceEqual(File.ReadAllBytes(Path.Combine(snap.Directory,f)))),"autotuner cancellation restores exact configuration/state");Check(!Core.Context().Contains("Radmin"),"unused Radmin adapter is not reported as Internet VPN");
  string originalProxy=Core.Proxy();if(originalProxy=="127.0.0.1:10809"){try{await Relay.On(17,token);Check(Core.Proxy()=="127.0.0.1:10819","native relay activation");var s=await Network.Http("Discord proxy","https://discord.com/api/v10/gateway","gateway",true,token,Core.Proxy());Check(s.Success,"Discord TLS passes through native relay");var live=Core.Read<RelayLive>(Core.PathOf("vpn-upload-live.json"));using(var p=Process.GetProcessById(live.PID)){p.Kill();p.WaitForExit(4000);}for(int n=0;n<50&&Core.Proxy()=="127.0.0.1:10819";n++)await Task.Delay(100);Check(Core.Proxy()==originalProxy,"native watchdog restores proxy after relay crash");}finally{Relay.Off();}}else lines.Add("SKIP: real relay integration requires Happ proxy 10809; local relay test passed");
 }
 static async Task MockStun(){using(var server=new UdpClient(new IPEndPoint(IPAddress.Loopback,0))){int port=((IPEndPoint)server.Client.LocalEndPoint).Port;var respond=Task.Run(async()=>{var request=await server.ReceiveAsync();byte[] a=(byte[])request.Buffer.Clone();a[0]=1;a[1]=1;await server.SendAsync(a,a.Length,request.RemoteEndPoint);});var probe=await Network.Stun("127.0.0.1",port,CancellationToken.None);await respond;Check(probe.Success,"STUN validates correct cookie/transaction");}using(var server=new UdpClient(new IPEndPoint(IPAddress.Loopback,0))){int port=((IPEndPoint)server.Client.LocalEndPoint).Port;var respond=Task.Run(async()=>{var request=await server.ReceiveAsync();byte[] a=(byte[])request.Buffer.Clone();a[0]=1;a[1]=1;a[8]^=1;await server.SendAsync(a,a.Length,request.RemoteEndPoint);});var probe=await Network.Stun("127.0.0.1",port,CancellationToken.None);await respond;Check(!probe.Success,"STUN rejects mismatched transaction");}}
 static async Task RelayTest(){var upstream=new TcpListener(IPAddress.Loopback,0);upstream.Start();int up=((IPEndPoint)upstream.LocalEndpoint).Port;var reserve=new TcpListener(IPAddress.Loopback,0);reserve.Start();int port=((IPEndPoint)reserve.LocalEndpoint).Port;reserve.Stop();int length=2*1024*1024;var sink=Task.Run(async()=>{using(var peer=await upstream.AcceptTcpClientAsync()){var stream=peer.GetStream();var b=new byte[8192];int got=0;while(got<length){int n=await stream.ReadAsync(b,0,b.Length);if(n==0)break;got+=n;}await stream.WriteAsync(new byte[]{42},0,1);return got;}});try{using(var relay=new UploadRelay(port,8,up))using(var client=new TcpClient()){await client.ConnectAsync(IPAddress.Loopback,port);var sw=Stopwatch.StartNew();byte[] b=new byte[length];await client.GetStream().WriteAsync(b,0,b.Length);byte[] reply=new byte[1];var read=client.GetStream().ReadAsync(reply,0,1);if(await Task.WhenAny(read,Task.Delay(10000))!=read)throw new TimeoutException("relay test");Check(await read==1&&reply[0]==42&&await sink==length,"relay forwards both directions without corruption");Check(sw.Elapsed.TotalSeconds>1.7&&sw.Elapsed.TotalSeconds<5,"relay enforces aggregate upload limit");}}finally{upstream.Stop();}}
}
}
